// ftruncate(2) - Truncate file referenced by fd
// Requires file to be open for writing (O_RDWR or O_WRONLY)

int fd;
off_t desired_len = 4096; // Target size in bytes

// Truncate/Extend file to desired_len
int status = ftruncate(fd, desired_len);

if (status == 0) {
    // Success. File is now exactly desired_len bytes.
    // If extended, new space is filled with NUL bytes.
} else {
    // status == -1 (Error)
    // Check errno for EBADF or EINVAL (not writable)
}
